function kb.relicWorth(Ffb,Gfb)
local Hfb=Gfb._unique_item_data and Gfb._unique_item_data._unique_relic_data
if not Hfb then
return 0
end
local Ifb=N.Items[Gfb.item_id]or{}
local Jfb,Kfb=V.types(Ffb.unit_id)
if Ifb.main_damage_type and Ifb.main_damage_type~=hLe[2971]and Ifb.main_damage_type~=Kfb then
return 0
end
local Lfb,Mfb=0,0
for Nfb,Ofb in pairs(Hfb._core_damage_type_buffs or{})do
if Jfb[Ofb.damage_type]then
Lfb=Lfb+(tonumber(Ofb.mul)or 0)+(tonumber(Ofb.add_upg)or 0)*0.01+(tonumber(Ofb.pen)or 0)*0.001
Mfb=Mfb+(tonumber(Ofb.crit)or 0)
end
end
Lfb=Lfb+Mfb*0.5
local Pfb=V.rows(Ffb.unit_id)
local Qfb=Pfb and Pfb[Pfb.max]
local Rfb=(Qfb and tonumber(Qfb.cd)or 0)*V.mult(Ffb,hLe[2719])
for Sfb,Tfb in pairs(Hfb._unique_relic_effects or{})do
local Ufb=type(Tfb.params)==hLe[2268]and Tfb.params or{}
if Tfb.id==hLe[3376]then
local Vfb=math.min(1,(tonumber(Ufb.extra_damage)or 0)*Rfb/math.max(1,tonumber(Ufb.time_interval)or 40))
local Wfb=V.DRONES and V.DRONES[Ffb.unit_id]
if Wfb and Wfb.late and Rfb>0 then
local Xfb=1/Rfb
Vfb=Vfb*Xfb/(Xfb+(tonumber(Wfb.max)or 0)*(tonumber(Wfb.late.dmg)or 0)*(tonumber(Wfb.hits)or 1)/math.max(0.1,tonumber(Wfb.late.cd)or 4))
end
Lfb=Lfb+Vfb
elseif Tfb.id==hLe[3377]then
Lfb=Lfb+(tonumber(Ufb.dmg_buff)or 0)*0.25
elseif Tfb.id==hLe[3378]then
Lfb=Lfb+(tonumber(Ufb.dmg_buff)or 0)*Mfb
elseif Tfb.id==hLe[3379]then
if Jfb.magic then
Lfb=0
else
Lfb=Lfb+(tonumber(Ufb.dmg_buff)or 0)*0.3
end
elseif Tfb.id==hLe[3380]then
if Jfb.water_damage then
Lfb=Lfb+0.05
end
elseif Tfb.id==hLe[2420]then
local Yfb=tonumber(Ufb.duration_buff)or tonumber(type(Tfb.static_params)==hLe[2268]and Tfb.static_params.duration_buff)or 2
local Zfb,_fb=pcall(V.attackInfo,Qfb and Qfb.atk,Qfb and Qfb.range)
local agb,bgb=Zfb and tonumber(_fb.burn)or 0,Zfb and tonumber(_fb.dot)or 0
if agb<=0 then
local cgb,dgb=pcall(pb.model,Ffb.unit_id,Zfb and _fb or nil,Qfb)
if cgb and type(dgb)==hLe[2268]and(tonumber(dgb.burnDot)or 0)>0 then
agb,bgb=dgb.burnDot,bgb+(tonumber(dgb.dot)or 0)
end
end
Lfb=Lfb+agb*math.max(0,Yfb-1)/(1+bgb)
end
end
return Lfb
end
function kb.relicPlan()
