local hqb=eqb..hLe[2598]..aqb.uuid..(fqb and hLe[3568]or hLe[3569])..hLe[3570]
local iqb=P.trainSim[_pb.key]
if iqb and iqb.sig==hqb and not iqb.pending and os.time()-(iqb.at or 0)<6*3600 then
return iqb
end
local jqb={sig=hqb,base=eqb,uuid=aqb.uuid,at=os.time(),ok=false,margin=gqb,pending=true}
P.trainSim[_pb.key]=jqb
local kqb,lqb=gb.levelFor(_pb)
if _pb.ldOverride then
kqb=_pb.ldOverride
end
if not kqb then
jqb.why,jqb.pending=hLe[3571],nil
