end
local mqb=gb.info(kqb,_pb.key,lqb,_pb.mod)
local nqb={}
for oqb,pqb in ipairs(bqb)do
local qqb=cqb.collection:get_unit_by_uuid(pqb)
if qqb then
table.insert(nqb,qqb)
end
end
local rqb=cqb.collection:get_unit_by_uuid(aqb.uuid)
if not rqb or#nqb==0 then
jqb.why,jqb.pending=hLe[3572],nil
return jqb
end
local sqb=gb.run(mqb,gb.teamFrom(nqb,mqb.map),{hpMul=1})
local tqb=mqb.infinite and gb.unbound(kqb)
local uqb=tqb and W.infTier(gb.run(mqb,gb.teamFrom(nqb,mqb.map),{hpMul=gqb}).wave)or nil
local vqb={}
for wqb,xqb in ipairs(nqb)do
if not V.isFarm(xqb.unit_id)then
local yqb,zqb=pcall(V.score,xqb,_pb.mod)
table.insert(vqb,{i=wqb,sc=yqb and zqb or 0})
end
end
table.sort(vqb,function(Aqb,Bqb)
return Aqb.sc<Bqb.sc
end)
local Cqb
for Dqb=1,math.min(3,#vqb)do
local Eqb=table.clone(nqb)
Eqb[vqb[Dqb].i]=rqb
local Fqb=gb.teamFrom(Eqb,mqb.map)
local Gqb=gb.run(mqb,Fqb,{hpMul=gqb,train=aqb.uuid})
if(tqb and W.infTier(Gqb.wave)>=uqb)or(not tqb and Gqb.won)then
local Hqb=gb.run(mqb,Fqb,{hpMul=1,train=aqb.uuid})
local Iqb=(Hqb.tk or 0)/math.max(0.5,Hqb.t/60)
if(Hqb.won or tqb)and(not Cqb or Iqb>math.max(Cqb.rate*1.5,Cqb.rate+1))then
Cqb={out=nqb[vqb[Dqb].i].unit_id,r=Hqb,rate=Iqb,trial=Eqb}
end
end
end
jqb.ownMin=sqb.t/60
if not Cqb then
jqb.why=tqb and string.format(hLe[3573],uqb,fqb and hLe[3574]or hLe[3575])or fqb and hLe[3576]or hLe[3577]
else
jqb.out,jqb.tk,jqb.minutes=Cqb.out,Cqb.r.tk or 0,Cqb.r.t/60
jqb.uuids={}
for Jqb,Kqb in ipairs(Cqb.trial)do
table.insert(jqb.uuids,Kqb.uuid)
end
jqb.slow=(sqb.won and not tqb)and jqb.minutes/math.max(0.1,jqb.ownMin)or 1
if jqb.tk<=0 and next(P.train.real)==nil then
jqb.why=hLe[3578]
elseif jqb.slow>ib.SLOW then
jqb.why=string.format(hLe[3579],math.floor((jqb.slow-1)*100+0.5))
