jqb.ok=true
end
end
jqb.pending=nil
F.log(1,hLe[3580],string.format(hLe[3581],_pb.label,V.name(aqb.id),jqb.out and(hLe[3582]..V.name(jqb.out))or hLe[1187],jqb.ok and string.format(hLe[3583],math.floor((ib.perRun(_pb.key,aqb.id)or 0)+0.5),aqb.what,jqb.minutes,jqb.ownMin)or tostring(jqb.why)))
