function eb.upgradeGain(BLb,CLb,DLb,ELb,FLb,GLb)
local HLb,ILb=CLb[DLb],CLb[DLb+1]
local JLb=(HLb.cd>0 and HLb.damage/HLb.cd or 0)
local KLb=(ILb.cd>0 and ILb.damage/ILb.cd or 0)*V.aoe(ILb.atk,ILb.range)/math.max(0.3,V.aoe(HLb.atk,HLb.range))
local LLb=JLb>0 and BLb*(KLb/JLb-1)or(GLb or 0)
local MLb=CLb[DLb+2]
if MLb and DLb+1<CLb.max and MLb.cd>0 and ILb.cd>0 and JLb>0 then
local NLb=BLb*((MLb.damage/MLb.cd)/JLb-1)
local OLb=ELb+MLb.cost*FLb
if NLb/OLb>LLb/ELb then
LLb=LLb+(NLb/OLb*ELb-LLb)*0.5
end
end
local PLb=(ILb.range or 0)>(HLb.range or 0)and(1+((ILb.range-HLb.range)/math.max(1,HLb.range)))or 1
return math.max(0,LLb)*PLb
end
function eb.dpsFor(QLb,RLb)
if RLb<=0 then
return 0
end
local SLb={}
for TLb,ULb in ipairs(QLb)do
if not ULb.farm and not ULb.grif and ULb.gain>0 then
table.insert(SLb,ULb)
end
end
table.sort(SLb,function(VLb,WLb)
return VLb.gain/VLb.cost>WLb.gain/WLb.cost
end)
local XLb,YLb=0,0
for ZLb,_Lb in ipairs(SLb)do
if RLb<=0 then
break
end
YLb=_Lb.gain/_Lb.cost
local aMb=math.min(1,RLb/_Lb.cost)
XLb=XLb+_Lb.gain*aMb
RLb=RLb-_Lb.cost*aMb
end
return XLb+math.max(0,RLb)*YLb*0.7
end
function eb.shieldDps(bMb,cMb,dMb,eMb,fMb,gMb,hMb)
if(eMb or 0)<=0 or(bMb or 0)<=0 or(fMb or 0)<=0 then
return bMb or 0
end
cMb,dMb,gMb=math.max(0.3,cMb or 2),math.max(1,dMb or 1),gMb or 1
local iMb=bMb*gMb*cMb/dMb
return fMb*dMb/((eMb/math.max(1,hMb or 1)+math.max(1,fMb/iMb))*cMb)/gMb
end
function eb.shieldGain(jMb,kMb,lMb,mMb,nMb,oMb,pMb,qMb)
local rMb,sMb=V.attackInfo(kMb.atk,kMb.range),V.attackInfo(mMb.atk,mMb.range)
local tMb=eb.shieldDps(jMb,(tonumber(kMb.cd)or 2)*(pMb or 1),rMb.n,nMb,oMb,qMb,rMb.hits)
local uMb=eb.shieldDps(lMb,(tonumber(mMb.cd)or 2)*(pMb or 1),sMb.n,nMb,oMb,qMb,sMb.hits)
local vMb=math.max(0,((tonumber(mMb.range)or 0)-(tonumber(kMb.range)or 0))/math.max(1,tonumber(kMb.range)or 1))
return math.max(0,uMb-tMb)+tMb*vMb
end
function eb.shieldWork(wMb,xMb,yMb,zMb,AMb,BMb,CMb,DMb,EMb)
if(zMb or 0)<=0 then
return 0
end
local FMb=3*zMb*(AMb or 1)/math.max(1,BMb or 20)
if(yMb or 0)>=FMb then
return 0
end
return math.max(1,wMb or 1)*math.max(1,EMb or 1)/math.max(0.3,xMb or 2)*math.min(CMb or 0,DMb or 0)
end
function eb.holdGain(GMb,HMb,IMb,JMb)
if not GMb or(HMb or 0)<=0 then
return 0
end
local KMb,LMb=tonumber(GMb.stun)or 0,tonumber(GMb.slowTime)or 0
if KMb<=0 and LMb<=0 then
return 0
end
local MMb,NMb=KMb>0 and KMb or LMb,KMb>0 and 1 or(tonumber(GMb.slowPct)or 0.3)
local OMb=NMb*MMb/(MMb+(tonumber(GMb.ccCd)or 8))
local PMb=OMb/math.max(0.1,1-OMb)
return HMb*PMb*U.clamp(IMb or 0.5,0,1)*math.min(1,(tonumber(GMb.n)or 1)/2)/(1+(JMb or 0))
end
function eb.bleedGain(QMb,RMb,SMb,TMb)
if(QMb or 0)<=0 then
return 0
end
local UMb=RMb or 0
for VMb,WMb in ipairs(SMb or{})do
UMb=math.max(UMb,(tonumber(WMb.hp)or 0)*0.5)
end
return QMb*UMb*(TMb and 0.5 or 1)
end
function eb.bleedShare(XMb,YMb,ZMb,_Mb)
if XMb<=0 or not YMb then
return 0
end
if _Mb then
return YMb==0 and XMb or XMb/(YMb+1)
end
return ZMb<YMb and XMb/(YMb-ZMb)or 0
end
function eb.keepsUp(aNb,bNb,cNb,dNb,eNb)
local fNb=aNb.coming
if not(fNb and#fNb>0 and aNb.waveSec)then
return true
end
local gNb=aNb.eff or 1
local hNb=aNb.money-cNb
local iNb=(aNb.teamDps or 0)*(aNb.shieldK or 1)+(dNb or 0)*gNb+eb.dpsFor(bNb,math.max(0,hNb))*gNb
local jNb=(aNb.farmNow or 0)+(eNb or 0)
local kNb=(aNb.roadSec or 130)*U.clamp(aNb.cover or 0.6,0.1,1)
local lNb=aNb.hpAlive or 0
for mNb,nNb in ipairs(fNb)do
lNb=math.max(0,lNb+nNb.hp-iNb*aNb.waveSec)
local oNb=iNb*kNb
if lNb>oNb then
return false,mNb,oNb/math.max(1,lNb)
end
if mNb< #fNb then
iNb=iNb+eb.dpsFor(bNb,(nNb.reward or 0)+jNb)*gNb*(0.85^mNb)
end
end
return true
end
function eb.decide(pNb,qNb)
local rNb=U.clamp(qNb.cover or 0.6,0.1,1)
