elseif O.farmFirst and wNb and not vNb and not bb.random then
ZNb=wNb
_Nb=string.format(hLe[4079],wNb.payback,qNb.left)
elseif wNb and uNb and ENb and not vNb and FNb then
ZNb=wNb
_Nb=string.format(hLe[4080],wNb.payback,qNb.left,qNb.coming and#qNb.coming or 0)
elseif JNb then
ZNb=wNb
_Nb=string.format(hLe[4081],wNb.payback,qNb.left)
elseif xNb then
ZNb=xNb
if INb then
_Nb=string.format(hLe[4082])
elseif vNb then
_Nb=string.format(hLe[4083],math.floor(qNb.pressure*100),math.floor(rNb*100))
