_Nb=string.format(hLe[4084],GNb or 1,math.floor((HNb or 0)*100))
elseif wNb and tNb then
_Nb=string.format(hLe[4085],math.min(999,math.floor(qNb.clearSec)),math.floor(sNb))
elseif wNb and qNb.piling then
_Nb=string.format(hLe[4086],qNb.enemies)
elseif wNb and not uNb then
_Nb=hLe[4087]
elseif wNb and not ENb then
_Nb=hLe[4088]
else
_Nb=hLe[4089]
