if oOb>pOb and(not lOb or oOb>lOb)then
jOb,lOb=nOb,oOb
end
end
end
end
if not jOb then
return nil,nil,string.format(hLe[4090],U.fmt(ZNb.cost),ZNb.what or hLe[2519],math.ceil((ZNb.cost-qNb.money)/PNb),math.floor(PNb),_Nb),{cost=ZNb.cost,what=ZNb.what,sec=math.ceil((ZNb.cost-qNb.money)/PNb),rate=math.floor(PNb),why=_Nb}
