for dtc,etc in pairs(P.dg.sim)do
if not ctc or(etc.at or 0)<ctc then
btc,ctc=dtc,etc.at or 0
end
end
P.dg.sim[btc]=nil
end
F.saveSoon()
return not Vsc.none and Vsc or nil
end
function jb.winP(ftc)
local gtc=tostring(math.min(4,math.max(1,math.ceil(ftc.d/5))))
local htc=P.dg.depth[gtc]or{runs=0,wins=0}
local itc=U.clamp(0.95-0.015*ftc.d,0.5,0.95)
local jtc=((tonumber(htc.wins)or 0)+itc*2)/((tonumber(htc.runs)or 0)+2)
local ktc,ltc=pcall(jb.sim,ftc)
if ktc and ltc and ltc.p then
local mtc,ntc=pcall(gb.styleP,ltc,ltc.zone==false and hLe[4201]or(ltc.zone and hLe[4135]or nil))
jtc=(jtc*2+(mtc and ntc or ltc.p))/3
end
return jtc,ktc and ltc or nil
end
function jb.hopeless(otc)
return otc~=nil and otc.won==false and(tonumber(otc.p)or 1)<=0.05
end
function jb.stake(ptc)
local qtc,rtc,stc=jb.res(ptc)
return rtc+2*stc
end
function jb.curseBar(ttc,utc)
local vtc=jb.stake(ttc)
if utc>=15 or vtc>=8 then
return 0.9,hLe[4362],vtc
end
if utc>=10 or vtc>=4 then
return 0.6,hLe[4363],vtc
end
return 0.1,hLe[4364],vtc
end
function jb.blindCurse(wtc,xtc)
return jb.fxText(jb.fx(wtc,xtc))==jb.fxText(jb.fx(wtc))
end
function jb.curseOk(ytc,ztc,Atc,Btc,Ctc)
local Dtc=tostring((jb.item(ytc)or{}).name or ytc)
local Etc,Ftc,Gtc=jb.curseBar(ztc,Atc)
if Etc>0.2 and jb.blindCurse(ztc,ytc)then
return false,string.format(hLe[4365],Dtc,Gtc)
end
local function Htc(Itc)
return Itc==nil or(tonumber(Itc.p)or 1)>=Etc
end
if Btc then
local Jtc,Ktc=pcall(jb.sim,Btc,nil,true)
if Jtc and not Htc(Ktc)then
return false,string.format(hLe[4366],Dtc,(Ftc:gsub(hLe[3965],hLe[4367])),tostring(Ktc.margin or hLe[2519]))
end
end
if#Ctc==0 then
return true
end
local Ltc
for Mtc,Ntc in ipairs(Ctc)do
local Otc,Ptc=pcall(jb.sim,Ntc,ytc,true)
if not Otc or Htc(Ptc)then
return true
end
if not Ltc or(tonumber(Ptc.p)or 0)>(tonumber(Ltc.p)or 0)then
Ltc=Ptc
end
end
return false,string.format(hLe[4368],Dtc,Ftc,tostring(Ltc and Ltc.margin or hLe[2519]))
end
function jb.curseGate(Qtc,Rtc)
local Stc=jb.roomCurse(Qtc.r)
