return jb.curseOk(Stc,Rtc,Qtc.d,Qtc,jb.after(Rtc,Qtc.choice))
end
function jb.payValue()
local Ttc,Utc=0,0
for Vtc,Wtc in ipairs(P.dg.pay or{})do
if type(Wtc.items)==hLe[2268]then
local Xtc=tonumber(Wtc.gems)or 0
for Ytc,Ztc in pairs(Wtc.items)do
if(tonumber(Ztc)or 0)>0 then
Xtc=Xtc+W.itemValue(Ytc,Ztc)
end
end
Ttc,Utc=Ttc+Xtc,Utc+1
end
end
if Utc<5 then
return nil
end
return Ttc/Utc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local _tc=type(P.dg)==hLe[2268]and type(P.dg.lossCalls)==hLe[2268]and P.dg.lossCalls or{}
return U.clamp(((tonumber(_tc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(_tc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(auc)
local buc,cuc=jb.curses(auc),jb.lives(auc)
local duc=jb.res(auc)
local euc=jb.rooms(auc)
local fuc={}
for guc,huc in ipairs(euc)do
table.insert(fuc,tostring(huc.r._r))
end
local iuc=table.concat(fuc,hLe[3170])..string.format(hLe[4369],cuc,duc,buc,W.teamSig())
if jb._pick and jb._pick.sig==iuc then
return jb._pick.x
end
local juc,kuc,luc,muc
for nuc,ouc in ipairs(euc)do
local puc=jb.roomValue(ouc,duc)
local quc,ruc
for suc,tuc in ipairs(jb.after(auc,ouc.choice))do
local uuc=jb.roomValue(tuc,duc)
if not quc or uuc>quc then
quc,ruc=uuc,tuc
end
end
local vuc,wuc=jb.winP(ouc)
local xuc=wuc~=nil and wuc.won==false
local yuc=cuc>=3 and 1 or(cuc==2 and 2 or 6)
local zuc=1-(1-vuc)^math.max(1,cuc)
ouc.oldScore=zuc*(puc+0.6*(quc or 0))-(1-vuc)*yuc
if xuc then
vuc=math.min(vuc,jb.lossWin())
zuc=vuc
yuc=yuc*2
end
ouc.p,ouc.sim,ouc.value,ouc.nextValue,ouc.nextRoom,ouc.simLost=vuc,wuc,puc,quc or 0,ruc,xuc or nil
ouc.score=zuc*(puc+0.6*(quc or 0))-(1-vuc)*yuc
local Auc,Buc,Cuc=pcall(jb.curseGate,ouc,auc)
if Auc and not Buc then
ouc.blocked=Cuc
end
if not ouc.blocked then
if not juc or ouc.score>juc.score then
juc=ouc
end
if xuc then
if not muc or ouc.score>muc.score then
muc=ouc
end
elseif not luc or ouc.score>luc.score then
luc=ouc
end
end
if not kuc or ouc.score>kuc.score then
kuc=ouc
end
end
if juc and juc.simLost and luc then
F.log(1,hLe[4370],string.format(hLe[4371],jb.roomName(juc),tostring(juc.sim and juc.sim.margin or hLe[2519]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(luc)))
elseif juc and muc and muc~=juc and muc.oldScore>juc.score then
F.log(1,hLe[4370],string.format(hLe[4372],jb.roomName(muc),tostring(muc.sim and muc.sim.margin or hLe[2519]),jb.roomName(juc)))
end
juc=juc or kuc
jb._pick={sig=iuc,x=juc,rooms=euc}
return juc
end
