jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(yvc,zvc)
local Avc=jb.cleared(yvc)
local Bvc=jb.res(yvc)
local Cvc=1+0.1*(jb.items(yvc)._curse_shop or 0)
local Dvc=jb.shopAhead(yvc)and math.ceil(jb.LUCK_RESERVE*Cvc)or 0
local Evc={}
local Fvc,Gvc={},0
for Hvc,Ivc in ipairs(jb.offers(zvc and zvc.data))do
Ivc.cost=math.ceil(Ivc.cost*Cvc)
table.insert(Fvc,tostring(jb.item(Ivc.id).name or Ivc.id))
if not Ivc.bought and not jb.isCurse(Ivc.id)then
Ivc.luck=tonumber(jb.item(Ivc.id).luck_increase)~=nil
Ivc.v=jb.itemValue(Ivc.id,yvc)
if not Ivc.luck and Ivc.v/math.max(1,Ivc.cost)<jb.MIN_WORTH then
Gvc=Gvc+1
elseif Ivc.v>0 and(Ivc.luck or Avc>=10 or Ivc.v/math.max(1,Ivc.cost)>=jb.TOP_WORTH)then
table.insert(Evc,Ivc)
end
end
end
table.sort(Evc,function(Jvc,Kvc)
if Jvc.luck~=Kvc.luck then
return Jvc.luck
end
return Jvc.v/math.max(1,Jvc.cost)>Kvc.v/math.max(1,Kvc.cost)
end)
local Lvc,Mvc,Nvc={},0,0
for Ovc,Pvc in ipairs(Evc)do
if Pvc.cost<=Bvc-(Pvc.luck and 0 or Dvc)then
if jb.buy(Pvc)then
Bvc=jb.res(jb.data())
table.insert(Lvc,string.format(hLe[4382],tostring(jb.item(Pvc.id).name or Pvc.id),Pvc.cost))
end
elseif Pvc.cost<=Bvc then
Nvc=Nvc+1
else
Mvc=Mvc+1
end
end
jb.note(string.format(hLe[4383],Avc,#Fvc>0 and table.concat(Fvc,hLe[2392])or hLe[4384],#Lvc>0 and(hLe[4385]..table.concat(Lvc,hLe[2392]))or(Avc<10 and hLe[4386]or(Nvc>0 and hLe[4387]or hLe[4388])),Bvc,Mvc>0 and string.format(hLe[4389],Mvc)or hLe[1187],Nvc>0 and string.format(hLe[4390],Nvc,Dvc)or hLe[1187],Gvc>0 and string.format(hLe[4391],Gvc)or hLe[1187]))
F.request(hLe[4392],hLe[4393])
