function jb.walletDiff(kwc,lwc)
local mwc={}
if lwc.gems~=kwc.gems then
table.insert(mwc,string.format(hLe[4399],lwc.gems-kwc.gems))
end
if lwc.gold~=kwc.gold then
table.insert(mwc,string.format(hLe[4400],lwc.gold-kwc.gold))
end
for nwc,owc in pairs(lwc.items)do
if owc~=(kwc.items[nwc]or 0)then
table.insert(mwc,string.format(hLe[4401],owc-(kwc.items[nwc]or 0),tostring(nwc)))
end
end
for pwc,qwc in pairs(lwc.units)do
if not kwc.units[pwc]then
table.insert(mwc,hLe[4402]..V.name(qwc))
end
end
if lwc.unique~=kwc.unique then
table.insert(mwc,string.format(hLe[4403],lwc.unique-kwc.unique))
end
return#mwc>0 and table.concat(mwc,hLe[2392])or hLe[4404]
end
function jb.openChests(rwc,swc)
local twc,uwc,vwc=jb.res(rwc)
local wwc=jb.lives(rwc)
local xwc=jb.cleared(rwc)
if not(swc or xwc>=jb.ROOMS or wwc<=1)then
jb.note(string.format(hLe[4405],xwc,uwc,vwc,jb.luck(rwc)))
F.request(hLe[4392],hLe[4393])
return
end
local ywc,zwc,Awc=0,0,0
local Bwc=tonumber(N.cur(hLe[2341]))or 0
local Cwc=jb.wallet()
for Dwc=1,uwc+vwc+4 do
local Ewc,Fwc,Gwc=jb.res(jb.data())
if Fwc+Gwc<=0 or Awc>=2 then
break
end
local Hwc,Iwc
if Fwc>0 then
Hwc,Iwc=F.request(hLe[4406],hLe[3994])
else
Hwc,Iwc=F.request(hLe[4406],hLe[3994],true)
end
if Hwc and Iwc~=nil then
F.log(1,hLe[4370],hLe[4407]..(type(Iwc)==hLe[2268]and U.json(U.plain(Iwc)):sub(1,300)or tostring(Iwc)))
end
local Jwc=U.now()
while U.now()-Jwc<4 do
local Kwc,Lwc,Mwc=jb.res(jb.data())
if Lwc<Fwc or Mwc<Gwc then
break
end
task.wait(0.25)
end
local Nwc,Owc,Pwc=jb.res(jb.data())
if Owc<Fwc then
ywc=ywc+(Fwc-Owc)
Awc=0
elseif Pwc<Gwc then
zwc=zwc+(Gwc-Pwc)
Awc=0
else
Awc=Awc+1
end
task.wait(1)
if Owc<Fwc or Pwc<Gwc then
local Qwc=jb.wallet()
local Rwc=jb.walletDiff(Cwc,Qwc)
F.log(1,hLe[4370],(Pwc<Gwc and hLe[4408]or hLe[4407])..Rwc)
P.dg.pay=P.dg.pay or{}
local Swc={}
for Twc,Uwc in pairs(Qwc.items)do
if Uwc~=(Cwc.items[Twc]or 0)then
Swc[Twc]=Uwc-(Cwc.items[Twc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Pwc<Gwc,gems=Qwc.gems-Cwc.gems,luck=jb.luck(rwc),paid=Rwc,items=Swc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Cwc=Qwc
end
end
jb.note(string.format(hLe[4409],ywc,zwc,swc and hLe[4410]or(wwc<=1 and hLe[4411]or hLe[4412]),jb.luck(rwc),(tonumber(N.cur(hLe[2341]))or 0)-Bwc))
local Vwc,Wwc,Xwc=jb.res(jb.data())
if(swc or xwc>=jb.ROOMS)and Wwc+Xwc>0 then
jb.note(string.format(hLe[4413],Wwc,Xwc))
W.rec(hLe[3029]).restUntil=os.time()+1800
return hLe[4414]
end
if not swc then
F.request(hLe[4392],hLe[4393])
end
end
function jb.act(Ywc)
