for bCc,cCc in pairs(aCc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[bCc.Name])then
local dCc={}
for eCc,fCc in ipairs(cCc.points or{})do
table.insert(dCc,fCc.part.Position)
end
local gCc=0
for hCc=2,#dCc do
gCc=gCc+(dCc[hCc]-dCc[hCc-1]).Magnitude
end
local iCc=0
for jCc=2,#dCc do
local kCc,lCc=dCc[jCc-1],dCc[jCc]
local mCc=(lCc-kCc).Magnitude
local nCc=math.max(1,math.floor(mCc/2))
for oCc=0,nCc-1 do
local pCc=kCc:Lerp(lCc,oCc/nCc)
table.insert(bb.samples,{pos=pCc,prog=(iCc+mCc*oCc/nCc)/math.max(1,gCc),lane=bCc.Name})
end
iCc=iCc+mCc
end
if dCc[#dCc]then
table.insert(bb.samples,{pos=dCc[#dCc],prog=1,lane=bCc.Name})
end
end
