function bb.readHidden(sCc)
local tCc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(tCc)~=hLe[2268]or not next(tCc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
