for vCc,wCc in pairs(sCc)do
if tCc[vCc.Name]and type(wCc.points)==hLe[2268]and#wCc.points>=2 then
local xCc={}
for yCc,zCc in ipairs(wCc.points)do
xCc[yCc]=U.flat(zCc.part.Position)
end
local ACc={}
for BCc,CCc in ipairs(bb.samples)do
local DCc=tostring(CCc.lane)
