for JCc=1,#xCc,math.max(1,math.floor(#xCc/20))do
local KCc=math.huge
for LCc,MCc in ipairs(HCc)do
local NCc=(U.flat(MCc.pos)-xCc[JCc]).Magnitude
if NCc<KCc then
KCc=NCc
end
end
ICc=ICc+KCc
end
if not FCc or ICc<FCc then
ECc,FCc=GCc,ICc
end
