local WCc,XCc=nil,math.huge
for YCc,ZCc in ipairs(ACc[ECc])do
local _Cc=(U.flat(ZCc.pos)-VCc).Magnitude
if _Cc<XCc then
XCc,WCc=_Cc,ZCc.prog
