RCc,SCc=bDc or RCc,SCc+math.abs(aDc)
else
PCc=WCc
end
QCc=WCc
if UCc%50==0 then
task.wait()
end
end
if QCc and TCc<=8 then
table.insert(OCc,math.floor(QCc*1000+0.5)/1000)
uCc=uCc or{}
uCc[vCc.Name]={from=math.floor((PCc or 0)*1000+0.5)/1000,len=math.floor(SCc*1000+0.5)/1000,turns=OCc,road=ECc}
end
end
end
if not uCc then
