end
local cDc=bb.ld.map
P.maps[cDc]=P.maps[cDc]or{}
local dDc=P.maps[cDc].hidden
P.maps[cDc].hidden=uCc
if type(dDc)~=hLe[2268]then
for eDc,fDc in pairs(uCc)do
F.log(1,hLe[2956],string.format(hLe[4506],eDc,fDc.len,tostring(fDc.road),math.floor((#fDc.turns-1)/2)))
