function bb.baseVerdict(jxd,kxd)
local lxd=(kxd.t or 0)-(jxd.t or 0)
if lxd<bb.BASE_WIN-1 then
return false
end
local mxd=((tonumber(jxd.base)or 0)-(tonumber(kxd.base)or 0))/lxd
if mxd<=0 or(tonumber(kxd.base)or 0)<=0 then
return false
end
local nxd=kxd.base/mxd
local oxd,pxd=0,0
local qxd,rxd=jxd.foes or{},kxd.foes or{}
for sxd,txd in pairs(rxd)do
if txd.prog>=bb.BASE_END then
oxd=oxd+txd.hp
local uxd=qxd[sxd]
if uxd then
pxd=pxd+math.max(0,uxd.hp-txd.hp)
end
end
end
for vxd,wxd in pairs(qxd)do
if wxd.prog>=bb.BASE_END and not rxd[vxd]then
pxd=pxd+wxd.hp
end
end
if oxd<=0 then
return false
end
local xxd=pxd/lxd
local yxd=xxd>0 and oxd/xxd or math.huge
local zxd={baseTime=nxd,loss=mxd,atEnd=oxd,rate=xxd,killTime=yxd}
return nxd<bb.BASE_SOON and yxd>nxd*bb.BASE_MARGIN,zxd
end
